"""Mission workflows with synthetic student/staff data and mocked Firebase."""
import json
from playwright.sync_api import sync_playwright
D={'schemaVersion':1,'revision':1,'streams':{},'classes':{cl:{'label':'Class '+cl,'sections':{'a':{'name':'A','stream':'','subjects':{'english':{'name':'English','code':''}},'students':{'one':{'name':'Synthetic Student '+cl,'roll':'001','subjects':{'english':True}}}}}} for cl in ['X','XII']}}
F={'schemaVersion':1,'revision':1,'classes':{'X':{'classId':'X','teachers':{'one':{'name':'Synthetic Teacher','designation':'TGT','subjects':'English','teachingSections':'A','status':'active'}},'roles':{'a':{'classTeacher':'one','coClassTeacher':''}}},'XII':{'classId':'XII','teachers':{},'roles':{}}}}
P={'schemaVersion':1,'includesStudents':True,'sections':{cl+'_a':{'classId':cl,'section':'A','stream':'','count':1,'students':{'one':{'name':'Synthetic Student '+cl,'roll':'001'}}} for cl in ['X','XII']}}
APP='export function initializeApp(c){return {options:c}} export function getApps(){return [];}'
AUTH="""export function getAuth(){return {}} export const browserLocalPersistence={};export async function setPersistence(){} export function onAuthStateChanged(a,cb){cb(window.__guest?null:{uid:'principal-test',getIdToken:async()=> 'mock-token'});} export async function signOut(){}"""
DB='''const draft=DRAFT,faculty=FACULTY,published=PUBLISHED;let mission=null;window.__missionReads=[];const listeners={};export function getDatabase(){return {}}export function ref(d,p){return p;}export async function get(p){window.__missionReads.push(p);return {val:()=> 'principal-test'};}export function onValue(p,cb,err){window.__missionReads.push(p);if(window.__denyMission&&p==='cbse/mission'){err({code:'PERMISSION_DENIED'});return ()=>{};}(listeners[p]||=[]).push(cb);cb({val:()=>p==='cbse/draft'?draft:p==='cbse/facultyDraft'?faculty:p==='cbse/public'?published:mission});return ()=>{};}
export async function runTransaction(p,fn){if(p!=='cbse/mission')throw Error('Unexpected write');const next=fn(structuredClone(mission));if(next===undefined)return {committed:false};mission=structuredClone(next);window.__savedMission=structuredClone(mission);for(const cb of listeners[p]||[])cb({val:()=>structuredClone(mission)});return {committed:true,snapshot:{val:()=>structuredClone(mission)}};}
'''.replace('DRAFT',json.dumps(D)).replace('FACULTY',json.dumps(F)).replace('PUBLISHED',json.dumps(P))
def sdk(route):
 url=route.request.url
 route.fulfill(content_type='application/javascript',body=APP if url.endswith('firebase-app.js') else AUTH if url.endswith('firebase-auth.js') else DB)
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox'])
 page=browser.new_page();page.route('https://www.gstatic.com/firebasejs/**',sdk)
 page.route('**/api/staff-access',lambda route:route.fulfill(status=503,content_type='application/json',body=json.dumps({'error':'Secure faculty PIN service needs Vercel credential activation.'})))
 page.goto('http://127.0.0.1:8000/cbse-mission.html');page.locator('#mission-tools').wait_for(state='visible')
 for width in [360,768,1440]:
  page.set_viewport_size({'width':width,'height':900});assert page.evaluate('document.documentElement.scrollWidth<=innerWidth')
 page.get_by_role('button',name='Class X',exact=True).click();page.get_by_role('button',name='Synthetic Student X',exact=True).click()
 page.get_by_role('heading',name='Synthetic Student X',exact=True).wait_for(state='visible')
 page.get_by_role('button',name='Edit basic/contact details').click();page.locator('[name=gender]').select_option('girl');page.locator('[name=guardian]').fill('Private Synthetic Guardian');page.locator('[name=phones]').fill('private-test-phone');page.locator('[name=location]').fill('Private Synthetic Address');page.locator('#mission-save').click();page.locator('#mission-editor').wait_for(state='hidden')
 assert 'Private Synthetic Address' in page.locator('#mission-view').inner_text()
 page.get_by_role('button',name='Tests & examinations',exact=True).click();page.get_by_role('button',name='Add test / PB examination').click();page.locator('[name=name]').fill('PB-1');page.locator('[name=type]').select_option('PB-1');page.locator('[name=date]').fill('2026-10-30');page.locator('#mission-save').click();page.locator('#mission-editor').wait_for(state='hidden')
 page.evaluate("location.hash='student=X%3Aa%3Aone'");page.get_by_role('button',name='Record marks',exact=True).click();page.locator('[name=examId]').select_option(index=1);page.locator('[name=subjectId]').select_option('english');page.locator('[name=score]').fill('25');page.locator('[name=maximum]').fill('100');page.locator('#mission-save').click();page.locator('#mission-editor').wait_for(state='hidden');assert page.locator('.band.red').count()>=1
 page.locator('#mission-thresholds').click();page.get_by_role('button',name='Add subject / examination rule').click();page.locator('[name=subjectId]').select_option('english');page.locator('[name=examId]').select_option(index=1);page.locator('[name=redBelow]').fill('20');page.locator('[name=greenFrom]').fill('75');page.locator('#mission-save').click();page.locator('#mission-editor').wait_for(state='hidden');page.evaluate("location.hash='student=X%3Aa%3Aone'");page.locator('.band.yellow').first.wait_for(state='visible')
 page.get_by_role('button',name='Record attendance',exact=True).click();page.locator('[name=status]').select_option('absent');page.locator('#mission-save').click();page.locator('#mission-editor').wait_for(state='hidden');assert '0.0%' in page.locator('#mission-view').inner_text()
 page.get_by_role('button',name='Add monitoring / comment').click();page.locator('[name=kind]').select_option('counselling');assert page.locator('[name=visibility]').input_value()=='restricted';page.locator('[name=notes]').fill('PRIVATE counselling follow-up');page.locator('#mission-save').click();page.locator('#mission-editor').wait_for(state='hidden')
 print('PASS linked student profile, private contact/gender, PB-1 marks, Red classification, attendance and restricted counselling notes')
 page.get_by_role('button',name='Counsellors & PRTs',exact=True).click();page.get_by_role('button',name='Add support-team member').click();page.locator('[name=name]').fill('Synthetic Counsellor');page.locator('[name=subjects]').fill('Study support');page.locator('#mission-save').click();page.locator('#mission-editor').wait_for(state='hidden')
 page.evaluate("location.hash='student=X%3Aa%3Aone'");page.get_by_role('button',name='Assign support task',exact=True).click();page.locator('[name=title]').fill('Weekly student support');page.locator('[name=staffId]').select_option(label='Synthetic Counsellor (counsellor)');page.locator('#mission-save').click();page.locator('#mission-editor').wait_for(state='hidden');assert 'Weekly student support' in page.locator('#mission-view').inner_text()
 page.get_by_role('button',name='Synthetic Counsellor',exact=True).click();page.get_by_role('heading',name='Synthetic Counsellor').wait_for(state='visible');assert 'Synthetic Student X' in page.locator('#mission-view').inner_text()
 page.get_by_role('button',name='Break / remedial timetable',exact=True).click();page.get_by_role('button',name='Add timetable slot').click();page.locator('[name=staffId]').select_option('X:one');page.locator('[name=purpose]').fill('Break practice');page.locator('[name=room]').fill('Lab');page.locator('#mission-save').click();page.locator('#mission-editor').wait_for(state='hidden')
 page.get_by_role('button',name='Add timetable slot').click();page.locator('[name=staffId]').select_option('X:one');page.locator('[name=purpose]').fill('Clashing class');page.locator('#mission-save').click();page.locator('#mission-editor-error').wait_for(state='visible');assert 'clash' in page.locator('#mission-editor-error').inner_text();page.locator('#mission-cancel').click()
 page.locator('#mission-pin-settings').click();page.locator('#mission-pin-message').filter(has_text='credential activation').wait_for();page.locator('#mission-close-pins').click()
 print('PASS counsellor task assignment, linked teacher/targeted-student profiles, timetable conflict and explicit PIN-service activation state')
 guest=browser.new_page();guest.add_init_script('window.__guest=true');guest.route('https://www.gstatic.com/firebasejs/**',sdk);guest.goto('http://127.0.0.1:8000/cbse-mission.html');guest.get_by_role('button',name='Class X',exact=True).click();guest.get_by_role('button',name='Synthetic Student X',exact=True).click();assert guest.locator('#mission-tools').is_hidden();assert 'Private Synthetic Address' not in guest.locator('#mission-view').inner_text();assert guest.evaluate('window.__missionReads')==['cbse/public']
 print('PASS public view reads only approved published data and cannot access private monitoring/contact records')
 browser.close()
